package main

import "fmt"

type DatabaseConfig struct {
	host     string
	port     int
	dbName   string
	maxOpen  int
	maxIdle  int
	sslMode  string
}

type DBOption func(*DatabaseConfig)

// TODO: implement the following options:
// - WithDBHost(host string) DBOption
// - WithDBPort(port int) DBOption
// - WithMaxOpenConns(n int) DBOption
// - WithMaxIdleConns(n int) DBOption
// - WithSSLMode(mode string) DBOption

func WithDBHost(host string) DBOption {
	return func(c *DatabaseConfig) { c.host = host }
}

func WithDBPort(port int) DBOption {
	return func(c *DatabaseConfig) { c.port = port }
}

func WithMaxOpenConns(n int) DBOption {
	return func(c *DatabaseConfig) { c.maxOpen = n }
}

func WithSSLMode(mode string) DBOption {
	return func(c *DatabaseConfig) { c.sslMode = mode }
}

// NewDatabase creates a DatabaseConfig with defaults
func NewDatabase(dbName string, opts ...DBOption) *DatabaseConfig {
	cfg := &DatabaseConfig{
		host:    "localhost",
		port:    5432,
		dbName:  dbName,
		maxOpen: 25,
		maxIdle: 5,
		sslMode: "disable",
	}
	for _, opt := range opts {
		opt(cfg)
	}
	return cfg
}

func main() {
	// Default config
	db1 := NewDatabase("myapp")
	fmt.Printf("db1: %+v\n", db1)

	// Custom config
	db2 := NewDatabase("production",
		WithDBHost("db.example.com"),
		WithDBPort(5433),
		WithMaxOpenConns(50),
		WithSSLMode("require"),
	)
	fmt.Printf("db2: %+v\n", db2)
}
